const WHITESPACE=/\s/,NUMBERS=/[0-9]/,LETTERS=/[a-z]/i,tokenizer=e=>{let t=0,n=[];for(;t<e.length;){let r=e[t];if("("!==r)if(")"!==r){if(!WHITESPACE.test(r)){if(NUMBERS.test(r)){let o="";for(;NUMBERS.test(r);)o+=r,r=e[++t];n.push({type:"number",value:o});continue}if('"'===r){let o="";for(r=e[++t];'"'!==r;)o+=r,r=e[++t];n.push({type:"string",value:o});continue}if(LETTERS.test(r)){let o="";for(;LETTERS.test(r);)o+=r,r=e[++t];n.push({type:"name",value:o});continue}throw new TypeError("Unkown Token:"+r)}t++}else n.push({type:"paren",value:")"}),t++;else n.push({type:"paren",value:"("}),t++}return n};module.exports=tokenizer;